"""Regenerate docs/cli-reference.md from the `tau2` CLI's own --help output.

Usage:
    UV_FROZEN=1 uv run python scripts/generate_cli_reference.py
"""

import argparse
import os
import sys
from pathlib import Path

OUTPUT = Path(__file__).resolve().parents[1] / "docs" / "cli-reference.md"

HEADER = """# CLI reference

<!-- Generated by scripts/generate_cli_reference.py. Do not edit by hand. -->

This page is the `--help` output of every `tau2` command, generated from the
CLI. Regenerate it after changing any option:

```bash
UV_FROZEN=1 uv run python scripts/generate_cli_reference.py
```

For a walkthrough, see [Getting started](getting-started.md) and
[Running simulations](running_simulations.md). Running `tau2` with no command
(or `tau2 intro`) prints a short overview in the terminal. The CLI covers the
airline domain in text (turn-based) mode only.

## Commands

| Command | Description |
|---|---|
"""


def capture_parser() -> argparse.ArgumentParser:
    """Build the real `tau2` parser by running main() up to parse_args()."""
    captured = {}

    def stop(self, *args, **kwargs):
        captured["parser"] = self
        raise SystemExit(0)

    original = argparse.ArgumentParser.parse_args
    argparse.ArgumentParser.parse_args = stop
    argv = sys.argv
    sys.argv = ["tau2"]
    try:
        from tau2.cli import main

        try:
            main()
        except SystemExit:
            pass
    finally:
        argparse.ArgumentParser.parse_args = original
        sys.argv = argv
    return captured["parser"]


def subcommands(parser: argparse.ArgumentParser):
    """Yield (name, help, subparser) for each direct subcommand."""
    for action in parser._actions:
        if isinstance(action, argparse._SubParsersAction):
            helps = {choice.dest: choice.help for choice in action._choices_actions}
            for name, sub in action.choices.items():
                yield name, helps.get(name) or "", sub


def help_block(path: list[str], parser: argparse.ArgumentParser, level: int) -> str:
    """One heading plus the command's help text."""
    heading = "#" * level
    return f"{heading} `{' '.join(path)}`\n\n```text\n{parser.format_help().rstrip()}\n```\n"


def render() -> str:
    """The full markdown page."""
    root = capture_parser()
    rows, sections = [], [help_block(["tau2"], root, 2)]
    for name, description, sub in subcommands(root):
        rows.append(f"| [`tau2 {name}`](#tau2-{name}) | {description} |")
        sections.append(help_block(["tau2", name], sub, 2))
        for child, _, child_parser in subcommands(sub):
            sections.append(help_block(["tau2", name, child], child_parser, 3))
    return HEADER + "\n".join(rows) + "\n\n" + "\n".join(sections)


if __name__ == "__main__":
    # Fixed width so the output does not depend on the terminal.
    os.environ["COLUMNS"] = "88"
    OUTPUT.write_text(render())
    print(f"Wrote {OUTPUT}")
